import subprocess, os, re
def run(args, inp=b"0123456789ABCDEF0123456789", env=None):
    e=dict(os.environ)
    if env: e.update(env)
    return subprocess.run(["./executable"]+args, input=inp, capture_output=True, env=e)
def show(l,args,inp=b"0123456789ABCDEF0123456789"):
    p=run(args,inp=inp)
    print("##",l)
    for line in p.stdout.decode().splitlines():
        plain=re.sub(r'\x1b\[[0-9;]*m','',line)
        print(len(plain), repr(plain))
    if p.stderr: print("err",p.stderr)
    print()
for base in ["binary","octal","decimal","hexadecimal"]:
    show(base, ["--color=never",f"--base={base}"])
for gs in ["1","2","4","8"]:
    show(f"group{gs}", ["--color=never",f"--group-size={gs}"])
for gs in ["2","4","8"]:
    show(f"group{gs} little", ["--color=never",f"--group-size={gs}","--endianness=little"])
show("group2 binary", ["--color=never","--group-size=2","--base=binary"], inp=b"\x01\x02\x03\x04\x05")
show("group4 decimal", ["--color=never","--group-size=4","--base=decimal"], inp=b"\x01\x02\x03\x04\x05\xff")
