{"command":"python3 - << 'PY'
import subprocess
def panels(args):
    p=subprocess.run(["./executable"]+args, input=b"0123456789ABCDEF0123456789ABCDEF", capture_output=True)
    lines=p.stdout.decode().splitlines()
    # if border none no header, use first line length
    return len(lines[0]) if lines else 0
configs=[]
for base,digits in [("hexadecimal",2),("octal",3),("decimal",3),("binary",8)]:
    for gs in [1,2,4,8]:
        H=2+(8//gs)*(gs*digits)+((8//gs)-1)
        for pos in [True,False]:
            for char in [True,False]:
                args=["--color=never",f"--base={base}",f"--group-size={gs}"]
                if not pos: args.append("--no-position")
                if not char: args.append("--no-characters")
                w=panels(args)
                # compute totals for 1,2
                def total(n):
                    t=1
                    if pos: t+=8+1
                    t+=n*H+(n-1)
                    if char: t+=1+n*8+(n-1)
                    t+=1
                    return t
                def E(n):
                    return total(n)-(n if char else 0)
                n = 1 if w==total(1) else 2 if w==total(2) else w
                print(f"{base:13} gs{gs} H{H:2} pos{int(pos)} char{int(char)} -> width{w:3} n={n} E1={E(1)} E2={E(2)} tot2={total(2)}")
PY"}

