import os, pty, subprocess, fcntl, termios, struct, select, re

def make_pty(cols):
    m,s=pty.openpty()
    fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH",24,cols,0,0))
    return m,s

def run_case(stdout_cols=None, stderr_cols=None, stdin_cols=None, args=["--color=never","--panels=auto","/tmp/t.bin"]):
    masters=[]
    slaves={}
    kwargs={}
    # stdin
    stdin_pipe=None
    if stdin_cols:
        m,s=make_pty(stdin_cols); masters.append(m); kwargs['stdin']=s; slaves['in']=s
    else:
        kwargs['stdin']=subprocess.PIPE
    if stdout_cols:
        m,s=make_pty(stdout_cols); masters.append(m); kwargs['stdout']=s; slaves['out']=s; out_master=m
    else:
        kwargs['stdout']=subprocess.PIPE; out_master=None
    if stderr_cols:
        m,s=make_pty(stderr_cols); masters.append(m); kwargs['stderr']=s; slaves['err']=s
    else:
        kwargs['stderr']=subprocess.PIPE
    e=dict(os.environ); e["TERM"]="xterm"
    p=subprocess.Popen(["./executable"]+args, env=e, **kwargs)
    for s in slaves.values(): os.close(s)
    if not stdin_cols:
        p.stdin.close()
    out=b""
    if out_master:
        while True:
            r,_,_=select.select([out_master],[],[],2)
            if not r: break
            try: d=os.read(out_master,65536)
            except: break
            if not d: break
            out+=d
        p.wait()
    else:
        out=p.stdout.read(); p.wait()
    for m in masters:
        try: os.close(m)
        except: pass
    text=out.decode(errors='replace').replace('\r\n','\n')
    plain=re.sub(r'\x1b\[[0-9;]*m','',text)
    lines=plain.splitlines()
    return len(lines[0]) if lines else 0, b'\x1b' in out, text[:100]

