//! A minimal Unix terminal-size helper.
//!
//! This provides just enough of the conventional `terminal_size` API for
//! terminal-width detection in this project and in Clap's help formatter.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: usize, ...) -> i32;
}

const TIOCGWINSZ: usize = 0x5413;

/// Return the size of the controlling terminal, checking stdout, then
/// stderr, then stdin. A file descriptor whose reported size has a zero
/// dimension is ignored.
pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [1_i32, 2, 0] {
        let mut winsize = Winsize::default();
        let result = unsafe { ioctl(fd, TIOCGWINSZ, &mut winsize as *mut Winsize) };
        if result == 0 && winsize.ws_col > 0 && winsize.ws_row > 0 {
            return Some((Width(winsize.ws_col), Height(winsize.ws_row)));
        }
    }
    None
}
EOF
