{"command":"cat > src/main.rs <<'RS'
use anyhow::{anyhow, bail, Context, Result};
use clap::{builder::PossibleValue, builder::ValueParser, Arg, ArgAction, Command};
use std::env;
use std::fs::File;
use std::io::{self, BufReader, BufWriter, IsTerminal, Read, Seek, SeekFrom, Stdin, Write};
use std::num::{NonZeroU64, NonZeroUsize};
use std::path::{Path, PathBuf};

mod tables;
use tables::{BRAILLE_TABLE, CP1047_TABLE, CP437_TABLE, GRADIENT_TABLE};

const RESET: &str = "\x1b[39m";
const FAILED_TO_JUMP: &str = "Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).";

fn main() {
    match run() {
        Ok(()) => {}
        Err(err) => {
            if is_broken_pipe(&err) {
                return;
            }
            let _ = writeln!(io::stderr(), "Error: {err:?}");
            std::process::exit(1);
        }
    }
}

fn is_broken_pipe(err: &anyhow::Error) -> bool {
    err.chain().any(|cause| {
        cause
            .downcast_ref::<io::Error>()
            .map(|io_err| io_err.kind() == io::ErrorKind::BrokenPipe)
            .unwrap_or(false)
    })
}

fn run() -> Result<()> {
    let matches = build_cli().get_matches();

    let plain = matches.get_flag("plain");

    if matches.get_flag("print-color-table") {
        print_color_table();
        return Ok(());
    }

    if let Some(shell) = matches.get_one::<String>("completion") {
        let script = match shell.as_str() {
            "bash" => include_str!("completions/bash.txt"),
            "elvish" => include_str!("completions/elvish.txt"),
            "fish" => include_str!("completions/fish.txt"),
            "powershell" => include_str!("completions/powershell.txt"),
            "zsh" => include_str!("completions/zsh.txt"),
            _ => unreachable!(),
        };
        print!("{script}");
        return Ok(());
    }

    let file_path = matches.get_one::<PathBuf>("FILE").cloned();
    let mut input = open_input(file_path.as_deref())?;

    // The block size has to be known before any other byte count is parsed,
    // because other counts can use the `block` unit.
    let block_size_arg = matches
        .get_one::<String>("block-size")
        .cloned()
        .unwrap_or_else(|| "512".to_string());
    let block_size = parse_block_size(&block_size_arg)?;

    // Mirrors the reference: a successfully parsed hexadecimal block size
    // makes it stop after opening the input, without producing output.
    if block_size.was_hex {
        return Ok(());
    }
    let block_size_value = block_size.value;

    let mut current_position: u64 = 0;
    if let Some(skip_arg) = matches.get_one::<String>("skip") {
        let skip = parse_signed_count(skip_arg, block_size_value)
            .with_context(|| format!("failed to parse `--skip` arg {skip_arg:?} as byte count"))?;
        current_position = input.apply_skip(skip)?;
    }

    let length: Option<u64> = if let Some(length_arg) = matches.get_one::<String>("length") {
        Some(parse_unsigned_arg("--length", length_arg, block_size_value)?)
    } else {
        None
    };

    let display_offset_arg = matches
        .get_one::<String>("display-offset")
        .cloned()
        .unwrap_or_else(|| "0".to_string());
    let display_offset =
        parse_unsigned_arg("--display-offset", &display_offset_arg, block_size_value)?;

    let base_arg = matches
        .get_one::<String>("base")
        .cloned()
        .unwrap_or_else(|| "hexadecimal".to_string());
    let base = parse_base(&base_arg)?;

    let panels_arg = parse_panels_arg(matches.get_one::<String>("panels"))?;
    let terminal_width = matches.get_one::<NonZeroUsize>("terminal-width").copied();

    // Effective display settings.
    let show_position = !plain && !matches.get_flag("no-position");
    let show_characters = if plain {
        false
    } else if matches.get_flag("characters") {
        true
    } else if matches.get_flag("no-characters") {
        false
    } else {
        true
    };

    let color_when = effective_value(&matches, "color", plain, "never", "always");
    let border_style_str = effective_value(&matches, "border", plain, "none", "unicode");
    let border = match border_style_str {
        "ascii" => BorderStyle::Ascii,
        "none" => BorderStyle::None,
        _ => BorderStyle::Unicode,
    };

    let use_color = use_color(color_when);
    let character_table = match matches
        .get_one::<String>("character-table")
        .map(String::as_str)
        .unwrap_or("default")
    {
        "ascii" => CharacterTable::Ascii,
        "codepage-1047" => CharacterTable::Codepage1047,
        "codepage-437" => CharacterTable::Codepage437,
        "braille" => CharacterTable::Braille,
        _ => CharacterTable::Default,
    };
    let color_scheme = match matches
        .get_one::<String>("color-scheme")
        .map(String::as_str)
        .unwrap_or("default")
    {
        "gradient" => ColorScheme::Gradient,
        _ => ColorScheme::Default,
    };
    let group_size: usize = matches
        .get_one::<String>("group-size")
        .map(|s| s.parse().unwrap_or(1))
        .unwrap_or(1);
    let little_endian = if matches.get_flag("little-endian") {
        true
    } else {
        matches
            .get_one::<String>("endianness")
            .map(|s| s == "little")
            .unwrap_or(false)
    };

    let digits = base.digits_per_byte();
    let hex_panel_width = panel_width(digits, group_size);
    let panels = resolve_panels(
        panels_arg,
        terminal_width,
        show_position,
        show_characters,
        hex_panel_width,
    );

    let palette = Palette::from_env();

    // Apply the length limit after skipping.
    let mut reader: Box<dyn Read> = if let Some(limit) = length {
        Box::new(input.take(limit))
    } else {
        Box::new(input)
    };

    if matches.get_flag("include") {
        let stdout = io::stdout();
        let mut writer = BufWriter::new(stdout.lock());
        let var_name = file_path.as_deref().map(include_var_name);
        print_include(&mut reader, &mut writer, var_name.as_deref())?;
        // Deliberately do not explicitly flush here: the reference drops
        // its buffered writer, ignoring a final flush error.
        return Ok(());
    }

    let mut printer = Printer::new(PrinterConfig {
        show_position,
        show_characters,
        use_color,
        border,
        panels,
        group_size,
        little_endian,
        base,
        character_table,
        color_scheme,
        palette,
        squeezing: !matches.get_flag("no-squeezing"),
        initial_offset: current_position.wrapping_add(display_offset),
    });

    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());
    printer.print_all(&mut reader, &mut writer)?;
    Ok(())
}

fn effective_value<'a>(
    matches: &'a clap::ArgMatches,
    id: &str,
    plain: bool,
    plain_default: &'a str,
    fallback: &'a str,
) -> &'a str {
    let value = matches
        .get_one::<String>(id)
        .map(String::as_str)
        .unwrap_or(fallback);
    if plain && matches.value_source(id) != Some(clap::parser::ValueSource::CommandLine) {
        plain_default
    } else {
        value
    }
}

fn open_input(path: Option<&Path>) -> Result<Input> {
    match path {
        Some(path) => {
            if path.is_dir() {
                bail!("'{}' is a directory.", path.display());
            }
            Ok(Input::File(BufReader::new(File::open(path)?)))
        }
        None => Ok(Input::Stdin(BufReader::new(io::stdin()))),
    }
}

fn include_var_name(path: &Path) -> String {
    path.file_name()
        .and_then(|name| name.to_str())
        .map(|name| {
            name.chars()
                .map(|c| if c.is_alphanumeric() { c } else { '_' })
                .collect::<String>()
        })
        .unwrap_or_else(|| "file".to_string())
}

fn print_include(
    reader: &mut dyn Read,
    writer: &mut dyn Write,
    var_name: Option<&str>,
) -> Result<()> {
    if let Some(var) = var_name {
        writeln!(writer, "unsigned char {var}[] = {{")?;
    }

    let mut total: u64 = 0;
    let mut current = read_chunk(reader, 12)?;
    if current.is_empty() {
        writeln!(writer)?;
    }
    while !current.is_empty() {
        total = total.wrapping_add(current.len() as u64);
        let next = read_chunk(reader, 12)?;
        write!(writer, "  ")?;
        for (idx, byte) in current.iter().enumerate() {
            if idx > 0 {
                write!(writer, ", ")?;
            }
            write!(writer, "0x{byte:02x}")?;
        }
        if !next.is_empty() {
            write!(writer, ",")?;
        }
        writeln!(writer)?;
        current = next;
    }

    if let Some(var) = var_name {
        writeln!(writer, "}};")?;
        writeln!(writer, "unsigned int {var}_len = {total};")?;
    }
    Ok(())
}

fn print_color_table() {
    let palette = Palette::from_env();
    let entries: [(Color, &str); 5] = [
        (palette.null, "⋄ NULL bytes (0x00)\n"),
        (
            palette.printable,
            "a ASCII printable characters (0x20 - 0x7E)\n",
        ),
        (
            palette.whitespace,
            "_ ASCII whitespace (0x09 - 0x0D, 0x20)\n",
        ),
        (
            palette.other,
            "• ASCII control characters (except NULL and whitespace)\n",
        ),
        (palette.nonascii, "× Non-ASCII bytes (0x80 - 0xFF)\n"),
    ];
    let mut output = String::from("hexyl color reference:\n\n");
    for (color, text) in entries {
        output.push_str(&color.prefix());
        output.push_str(text);
        output.push_str(RESET);
    }
    print!("{output}");
}

