// ---------------------------------------------------------------------------
// Byte-count parsing
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SignedCount {
    Positive(u64),
    Negative(u64),
}

struct BlockSize {
    value: i64,
    was_hex: bool,
}

fn unit_multiplier(unit: &str, block_size: Option<i64>) -> Option<Result<i64>> {
    // Return None for an unknown unit, Some(Ok(multiplier)) for a known
    // unit, and Some(Err(_)) for the specially-reported `block` unit when
    // no block size is available (i.e. while parsing --block-size itself).
    if unit.is_empty() {
        return Some(Ok(1));
    }
    let multiplier = if unit.eq_ignore_ascii_case("kB") {
        1_000
    } else if unit.eq_ignore_ascii_case("MB") {
        1_000_000
    } else if unit.eq_ignore_ascii_case("GB") {
        1_000_000_000
    } else if unit.eq_ignore_ascii_case("TB") {
        1_000_000_000_000
    } else if unit.eq_ignore_ascii_case("KiB") {
        1_024
    } else if unit.eq_ignore_ascii_case("MiB") {
        1_048_576
    } else if unit.eq_ignore_ascii_case("GiB") {
        1_073_741_824
    } else if unit.eq_ignore_ascii_case("TiB") {
        1_099_511_627_776
    } else if unit.eq_ignore_ascii_case("block") || unit.eq_ignore_ascii_case("blocks") {
        match block_size {
            Some(size) => size,
            None => {
                return Some(Err(anyhow!(
                    "can not use 'block(s)' as a unit to specify block size"
                )))
            }
        }
    } else {
        return None;
    };
    Some(Ok(multiplier))
}

fn is_valid_unit(unit: &str) -> bool {
    matches!(
        (),
        _ if unit.eq_ignore_ascii_case("kB")
            || unit.eq_ignore_ascii_case("MB")
            || unit.eq_ignore_ascii_case("GB")
            || unit.eq_ignore_ascii_case("TB")
            || unit.eq_ignore_ascii_case("KiB")
            || unit.eq_ignore_ascii_case("MiB")
            || unit.eq_ignore_ascii_case("GiB")
            || unit.eq_ignore_ascii_case("TiB")
            || unit.eq_ignore_ascii_case("block")
            || unit.eq_ignore_ascii_case("blocks")
    )
}

fn parse_hex_magnitude(hex: &str) -> Result<i64> {
    if let Some(sign) = hex.chars().next() {
        if sign == '+' || sign == '-' {
            if hex.len() == 1 {
                bail!("no digits found after sign, did you forget to write them?");
            }
            bail!("found '{sign}' sign after hex prefix (\"0x\"); signs should go before it");
        }
    }
    i64::from_str_radix(hex, 16).context("failed to parse integer part")
}

fn parse_signed_count(input: &str, block_size: i64) -> Result<SignedCount> {
    if input.is_empty() {
        bail!("no character data found, did you forget to write it?");
    }

    let (negative, rest) = match input.strip_prefix('-') {
        Some(rest) => (true, rest),
        None => match input.strip_prefix('+') {
            Some(rest) => (false, rest),
            None => (false, input),
        },
    };
    if rest.is_empty() {
        bail!("no digits found after sign, did you forget to write them?");
    }

    if let Some(hex) = rest.strip_prefix("0x") {
        let magnitude = parse_hex_magnitude(hex)? as u64;
        return Ok(if negative {
            SignedCount::Negative(magnitude)
        } else {
            SignedCount::Positive(magnitude)
        });
    }

    let digit_end = rest
        .find(|c: char| !c.is_ascii_digit())
        .unwrap_or(rest.len());
    if digit_end == 0 {
        if is_valid_unit(rest) {
            bail!("{rest:?} is a valid unit, but an integer should come before it");
        }
        bail!("{rest:?} is not of the expected form <pos-integer>[<unit>]");
    }
    let (digits, unit) = rest.split_at(digit_end);
    let multiplier = match unit_multiplier(unit, Some(block_size)) {
        Some(Ok(value)) => value,
        Some(Err(err)) => return Err(err),
        None => bail!("invalid unit {unit:?}"),
    };
    let count: i64 = digits.parse().context("failed to parse integer part")?;
    let value = count.checked_mul(multiplier).ok_or_else(|| {
        anyhow!("count multiplied by the unit overflowed a signed 64-bit integer; are you sure it should be that big?")
    })?;
    let magnitude = value as u64;
    Ok(if negative {
        SignedCount::Negative(magnitude)
    } else {
        SignedCount::Positive(magnitude)
    })
}

fn parse_unsigned_arg(arg_name: &str, input: &str, block_size: i64) -> Result<u64> {
    let context = || format!("failed to parse `{arg_name}` arg {input:?} as byte count");
    let parsed = parse_signed_count(input, block_size).with_context(context)?;
    match parsed {
        SignedCount::Positive(value) => Ok(value),
        SignedCount::Negative(_) => Err(anyhow!(
            "negative offset specified, but only positive offsets (counts) are accepted in this context"
        ))
        .with_context(context),
    }
}

fn parse_block_size(input: &str) -> Result<BlockSize> {
    if input.is_empty() {
        bail!("no character data found, did you forget to write it?");
    }

    if let Some(hex) = input.strip_prefix("0x") {
        let value = parse_hex_magnitude(hex)?;
        if value == 0 {
            bail!("block size argument must be positive");
        }
        return Ok(BlockSize {
            value,
            was_hex: true,
        });
    }

    let digit_end = input
        .find(|c: char| !c.is_ascii_digit())
        .unwrap_or(input.len());
    if digit_end == 0 {
        if is_valid_unit(input) {
            bail!("{input:?} is a valid unit, but an integer should come before it");
        }
        bail!("{input:?} is not of the expected form <pos-integer>[<unit>]");
    }
    let (digits, unit) = input.split_at(digit_end);
    // Validate the unit before parsing the integer, but report the
    // `block` unit only after the integer has been parsed: that ordering
    // is observable for overflowing integer parts. unit_multiplier()
    // with no available block size encodes that pending error for us.
    let multiplier_result = match unit_multiplier(unit, None) {
        Some(result) => result,
        None => bail!("invalid unit {unit:?}"),
    };
    let count: i64 = digits.parse().context("failed to parse integer part")?;
    let multiplier = multiplier_result?;
    let value = count.checked_mul(multiplier).ok_or_else(|| {
        anyhow!("count multiplied by the unit overflowed a signed 64-bit integer; are you sure it should be that big?")
    })?;
    if value == 0 {
        bail!("block size argument must be positive");
    }
    Ok(BlockSize {
        value,
        was_hex: false,
    })
}

// ---------------------------------------------------------------------------
// Other option parsing
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Base {
    Binary,
    Octal,
    Decimal,
    Hexadecimal,
}

impl Base {
    fn digits_per_byte(self) -> usize {
        match self {
            Base::Binary => 8,
            Base::Octal => 3,
            Base::Decimal => 3,
            Base::Hexadecimal => 2,
        }
    }

    fn representations(self) -> [String; 256] {
        std::array::from_fn(|i| {
            let byte = i as u8;
            match self {
                Base::Binary => format!("{byte:08b}"),
                Base::Octal => format!("{byte:03o}"),
                Base::Decimal => format!("{byte:03}"),
                Base::Hexadecimal => format!("{byte:02x}"),
            }
        })
    }
}

fn parse_base(input: &str) -> Result<Base> {
    if let Ok(number) = input.parse::<u8>() {
        return match number {
            2 => Ok(Base::Binary),
            8 => Ok(Base::Octal),
            10 => Ok(Base::Decimal),
            16 => Ok(Base::Hexadecimal),
            _ => bail!("The number provided is not a valid base. Valid bases are 2, 8, 10, and 16."),
        };
    }
    match input {
        "binary" | "bin" | "b" => Ok(Base::Binary),
        "octal" | "oct" | "o" => Ok(Base::Octal),
        "decimal" | "dec" | "d" => Ok(Base::Decimal),
        "hexadecimal" | "hex" | "x" => Ok(Base::Hexadecimal),
        _ => bail!("The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\"."),
    }
}

#[derive(Debug, Clone, Copy)]
enum PanelsArg {
    Auto,
    Count(u64),
}

fn parse_panels_arg(input: Option<&String>) -> Result<Option<PanelsArg>> {
    let Some(input) = input else {
        return Ok(None);
    };
    if input == "auto" {
        return Ok(Some(PanelsArg::Auto));
    }
    let parsed = input
        .parse::<NonZeroU64>()
        .with_context(|| format!("failed to parse `--panels` arg {input:?} as unsigned nonzero integer"))?;
    Ok(Some(PanelsArg::Count(parsed.get())))
}

fn panels_that_fit(term_width: usize, show_position: bool, show_characters: bool, hex_panel_width: usize) -> usize {
    let constant = if show_position { 10_usize } else { 1_usize };
    let per_panel = hex_panel_width + 1 + if show_characters { 8 } else { 0 };
    if term_width < constant + per_panel {
        1
    } else {
        (term_width - constant) / per_panel
    }
}

fn detected_terminal_width() -> usize {
    terminal_size::terminal_size()
        .map(|(width, _)| width.0 as usize)
        .unwrap_or(80)
}

fn resolve_panels(
    arg: Option<PanelsArg>,
    terminal_width: Option<NonZeroUsize>,
    show_position: bool,
    show_characters: bool,
    hex_panel_width: usize,
) -> usize {
    match arg {
        Some(PanelsArg::Count(count)) => count as usize,
        Some(PanelsArg::Auto) => panels_that_fit(
            detected_terminal_width(),
            show_position,
            show_characters,
            hex_panel_width,
        ),
        None => {
            if let Some(width) = terminal_width {
                panels_that_fit(width.get(), show_position, show_characters, hex_panel_width)
            } else {
                let fitting = panels_that_fit(
                    detected_terminal_width(),
                    show_position,
                    show_characters,
                    hex_panel_width,
                );
                if fitting >= 2 {
                    2
                } else {
                    1
                }
            }
        }
    }
}

fn panel_width(digits_per_byte: usize, group_size: usize) -> usize {
    let groups = 8 / group_size;
    2 + groups * group_size * digits_per_byte + (groups - 1)
}

// ---------------------------------------------------------------------------
// Colors
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Color {
    Ansi(u8),
    Rgb(u8, u8, u8),
    GradientRgb(u8, u8, u8),
}

impl Color {
    fn prefix(self) -> String {
        match self {
            Color::Ansi(code) => format!("\x1b[{code}m"),
            Color::Rgb(r, g, b) => format!("\x1b[38;2;{r};{g};{b}m"),
            Color::GradientRgb(r, g, b) => format!("\x1b[38;2;{r:03};{g:03};{b:03}m"),
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct Palette {
    null: Color,
    printable: Color,
    whitespace: Color,
    other: Color,
    nonascii: Color,
    offset: Color,
}

impl Palette {
    fn from_env() -> Self {
        Self {
            null: color_from_env("HEXYL_COLOR_NULL", Color::Ansi(90)),
            printable: color_from_env("HEXYL_COLOR_ASCII_PRINTABLE", Color::Ansi(36)),
            whitespace: color_from_env("HEXYL_COLOR_ASCII_WHITESPACE", Color::Ansi(32)),
            other: color_from_env("HEXYL_COLOR_ASCII_OTHER", Color::Ansi(32)),
            nonascii: color_from_env("HEXYL_COLOR_NONASCII", Color::Ansi(33)),
            offset: color_from_env("HEXYL_COLOR_OFFSET", Color::Ansi(90)),
        }
    }
}

fn color_from_env(name: &str, default: Color) -> Color {
    match env::var(name) {
        Ok(value) => parse_color_name(&value).unwrap_or(default),
        Err(_) => default,
    }
}

fn parse_color_name(value: &str) -> Option<Color> {
    let code = match value {
        "black" => 30,
        "red" => 31,
        "green" => 32,
        "yellow" => 33,
        "blue" => 34,
        "magenta" | "purple" => 35,
        "cyan" => 36,
        "white" => 37,
        "bright black" => 90,
        "bright red" => 91,
        "bright green" => 92,
        "bright yellow" => 93,
        "bright blue" => 94,
        "bright magenta" => 95,
        "bright cyan" => 96,
        "bright white" => 97,
        _ => {
            let hex = value.strip_prefix('#')?;
            if hex.len() != 6 {
                return None;
            }
            let r = u8::from_str_radix(hex.get(0..2)?, 16).ok()?;
            let g = u8::from_str_radix(hex.get(2..4)?, 16).ok()?;
            let b = u8::from_str_radix(hex.get(4..6)?, 16).ok()?;
            return Some(Color::Rgb(r, g, b));
        }
    };
    Some(Color::Ansi(code))
}

fn use_color(when: &str) -> bool {
    match when {
        "always" => env::var_os("NO_COLOR").is_none(),
        "auto" => auto_color(),
        "never" => false,
        "force" => true,
        _ => false,
    }
}

fn force_color_value(value: &str) -> bool {
    if value == "false" {
        return false;
    }
    match value.parse::<u8>() {
        Ok(0) => false,
        Ok(_) => true,
        Err(_) => true,
    }
}

fn auto_color() -> bool {
    if env::var_os("NO_COLOR").is_some() {
        return false;
    }
    if let Ok(value) = env::var("FORCE_COLOR") {
        if force_color_value(&value) {
            return true;
        }
        // An explicitly disabled FORCE_COLOR supersedes CLICOLOR_FORCE
        // for the forcing decision, but a terminal may still support
        // color on its own.
        return terminal_supports_color();
    }
    if let Ok(value) = env::var("CLICOLOR_FORCE") {
        if value != "0" {
            return true;
        }
    }
    terminal_supports_color()
}

fn terminal_supports_color() -> bool {
    if !io::stdout().is_terminal() {
        return false;
    }
    if let Ok(term) = env::var("TERM") {
        if term == "dumb" {
            return false;
        }
        return true;
    }
    if env::var_os("TERM").is_some() {
        return true;
    }
    if env::var_os("COLORTERM").is_some() {
        return true;
    }
    if let Ok(value) = env::var("CLICOLOR") {
        if value != "0" {
            return true;
        }
    }
    if ci_supports_color() {
        return true;
    }
    if let Ok(program) = env::var("TERM_PROGRAM") {
        if program == "iTerm.app" || program == "Apple_Terminal" {
            return true;
        }
    }
    false
}

fn ci_supports_color() -> bool {
    if let Ok(value) = env::var("CI") {
        if value == "true" || value == "1" {
            return true;
        }
    }
    if let Ok(value) = env::var("CI_NAME") {
        if value == "codeship" {
            return true;
        }
    }
    [
        "CIRCLECI",
        "TRAVIS",
        "APPVEYOR",
        "GITLAB_CI",
        "BUILDKITE",
        "DRONE",
        "CIRRUS_CI",
        "JENKINS_URL",
    ]
    .iter()
    .any(|name| env::var_os(name).is_some())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ColorScheme {
    Default,
    Gradient,
}

fn byte_color(byte: u8, scheme: ColorScheme, palette: &Palette) -> Color {
    if scheme == ColorScheme::Gradient {
        let (r, g, b) = GRADIENT_TABLE[byte as usize];
        return Color::GradientRgb(r, g, b);
    }
    if byte == 0 {
        palette.null
    } else if byte.is_ascii_whitespace() {
        palette.whitespace
    } else if (0x21..=0x7e).contains(&byte) {
        palette.printable
    } else if byte < 0x80 {
        palette.other
    } else {
        palette.nonascii
    }
}

// ---------------------------------------------------------------------------
// Input handling
// ---------------------------------------------------------------------------

enum Input {
    File(BufReader<File>),
    Stdin(BufReader<Stdin>),
}

impl Read for Input {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Input::File(reader) => reader.read(buf),
            Input::Stdin(reader) => reader.read(buf),
        }
    }
}

impl Input {
    fn discard(&mut self, amount: u64) -> Result<()> {
        let mut limited = self.take(amount);
        io::copy(&mut limited, &mut io::sink())?;
        Ok(())
    }

    fn apply_skip(&mut self, skip: SignedCount) -> Result<u64> {
        match skip {
            SignedCount::Positive(amount) => match self {
                Input::File(reader) => match reader.seek(SeekFrom::Start(amount)) {
                    Ok(position) => Ok(position),
                    Err(_) => {
                        // Some file objects (pipes reached through /dev/stdin,
                        // for example) cannot seek. Skip by reading instead.
                        let mut limited = reader.take(amount);
                        io::copy(&mut limited, &mut io::sink())?;
                        Ok(amount)
                    }
                },
                Input::Stdin(_) => {
                    self.discard(amount)?;
                    Ok(amount)
                }
            },
            SignedCount::Negative(amount) => match self {
                Input::File(reader) => reader
                    .seek(SeekFrom::End(-(amount as i64)))
                    .map_err(|_| anyhow!(FAILED_TO_JUMP)),
                Input::Stdin(_) => bail!(FAILED_TO_JUMP),
            },
        }
    }
}

fn read_chunk(reader: &mut dyn Read, size: usize) -> Result<Vec<u8>> {
    let mut buffer = vec![0_u8; size];
    let mut filled = 0_usize;
    while filled < size {
        match reader.read(&mut buffer[filled..]) {
            Ok(0) => break,
            Ok(read) => filled += read,
            Err(err) if err.kind() == io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err.into()),
        }
    }
    buffer.truncate(filled);
    Ok(buffer)
}

// ---------------------------------------------------------------------------
// Printer
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BorderStyle {
    Unicode,
    Ascii,
    None,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CharacterTable {
    Default,
    Ascii,
    Codepage1047,
    Codepage437,
    Braille,
}

struct PrinterConfig {
    show_position: bool,
    show_characters: bool,
    use_color: bool,
    border: BorderStyle,
    panels: usize,
    group_size: usize,
    little_endian: bool,
    base: Base,
    character_table: CharacterTable,
    color_scheme: ColorScheme,
    palette: Palette,
    squeezing: bool,
    initial_offset: u64,
}

struct Printer {
    config: PrinterConfig,
    hex_panel_width: usize,
    empty_hex_panel_width: usize,
    bytes_per_line: usize,
    representations: [String; 256],
    byte_colors: [Color; 256],
    current_offset: u64,
    previous_chunk: Option<Vec<u8>>,
    squeeze_active: bool,
}

impl Printer {
    fn new(config: PrinterConfig) -> Self {
        let hex_panel_width = panel_width(config.base.digits_per_byte(), config.group_size);
        let empty_hex_panel_width = panel_width(2, config.group_size);
        let bytes_per_line = config.panels.checked_mul(8).unwrap_or(usize::MAX);
        let representations = config.base.representations();
        let palette = config.palette;
        let scheme = config.color_scheme;
        let byte_colors = std::array::from_fn(|i| byte_color(i as u8, scheme, &palette));
        Self {
            current_offset: config.initial_offset,
            config,
            hex_panel_width,
            empty_hex_panel_width,
            bytes_per_line,
            representations,
            byte_colors,
            previous_chunk: None,
            squeeze_active: false,
        }
    }

    fn major_char(&self) -> char {
        match self.config.border {
            BorderStyle::Unicode => '│',
            BorderStyle::Ascii => '|',
            BorderStyle::None => ' ',
        }
    }

    fn inner_char(&self) -> char {
        match self.config.border {
            BorderStyle::Unicode => '┊',
            BorderStyle::Ascii => '|',
            BorderStyle::None => ' ',
        }
    }

    fn print_all(&mut self, reader: &mut dyn Read, writer: &mut dyn Write) -> Result<()> {
        let first = read_chunk(reader, self.bytes_per_line)?;
        if first.is_empty() {
            self.print_empty(writer)?;
            writer.flush()?;
            return Ok(());
        }

        if self.config.border != BorderStyle::None {
            self.print_border_line(writer, true, self.hex_panel_width)?;
        }
        self.process_chunk(writer, &first)?;
        loop {
            let chunk = read_chunk(reader, self.bytes_per_line)?;
            if chunk.is_empty() {
                break;
            }
            self.process_chunk(writer, &chunk)?;
        }
        if self.squeeze_active {
            self.print_final_line(writer)?;
        }
        if self.config.border != BorderStyle::None {
            self.print_border_line(writer, false, self.hex_panel_width)?;
        }
        writer.flush()?;
        Ok(())
    }

    fn process_chunk(&mut self, writer: &mut dyn Write, chunk: &[u8]) -> Result<()> {
        let is_repeat = self.config.squeezing
            && chunk.len() == self.bytes_per_line
            && !chunk.is_empty()
            && chunk.iter().all(|byte| *byte == chunk[0])
            && self.previous_chunk.as_deref() == Some(chunk);

        if is_repeat {
            if !self.squeeze_active {
                self.print_squeeze_line(writer)?;
                self.squeeze_active = true;
            }
        } else {
            self.print_data_line(writer, chunk, self.current_offset)?;
            self.squeeze_active = false;
        }

        self.current_offset = self.current_offset.wrapping_add(chunk.len() as u64);
        self.previous_chunk = Some(chunk.to_vec());
        Ok(())
    }

    fn column_widths(&self, hex_panel_width: usize) -> Vec<usize> {
        let mut widths = Vec::new();
        if self.config.show_position {
            widths.push(8);
        }
        widths.extend(std::iter::repeat(hex_panel_width).take(self.config.panels));
        if self.config.show_characters {
            widths.extend(std::iter::repeat(8).take(self.config.panels));
        }
        widths
    }

    fn print_border_line(
        &self,
        writer: &mut dyn Write,
        top: bool,
        hex_panel_width: usize,
    ) -> Result<()> {
        let (left, join, right, horizontal) = match (self.config.border, top) {
            (BorderStyle::Unicode, true) => ('┌', '┬', '┐', '─'),
            (BorderStyle::Unicode, false) => ('└', '┴', '┘', '─'),
            (BorderStyle::Ascii, _) => ('+', '+', '+', '-'),
            (BorderStyle::None, _) => return Ok(()),
        };
        let widths = self.column_widths(hex_panel_width);
        let mut line = String::new();
        line.push(left);
        for (idx, width) in widths.iter().enumerate() {
            if idx > 0 {
                line.push(join);
            }
            line.extend(std::iter::repeat(horizontal).take(*width));
        }
        line.push(right);
        writeln!(writer, "{line}")?;
        Ok(())
    }

    fn print_empty(&self, writer: &mut dyn Write) -> Result<()> {
        if self.config.border != BorderStyle::None {
            self.print_border_line(writer, true, self.empty_hex_panel_width)?;
        }

        // This intentionally follows the reference's special empty-output
        // layout: Unicode vertical bars and exactly two data panels,
        // regardless of the configured panel count and border style.
        let mut line = String::from("│");
        if self.config.show_position {
            line.push_str(&" ".repeat(8));
            line.push('│');
        }
        line.push_str(&format!(
            "{:<width$}",
            " No content",
            width = self.empty_hex_panel_width
        ));
        line.push('│');
        line.push_str(&" ".repeat(self.empty_hex_panel_width));
        if self.config.show_characters {
            line.push('│');
            line.push_str(&" ".repeat(8));
            line.push('│');
            line.push_str(&" ".repeat(8));
        }
        line.push('│');
        writeln!(writer, "{line}")?;

        if self.config.border != BorderStyle::None {
            self.print_border_line(writer, false, self.empty_hex_panel_width)?;
        }
        Ok(())
    }

    fn panel_slice<'a>(&self, chunk: &'a [u8], panel: usize) -> &'a [u8] {
        let start = panel * 8;
        if start >= chunk.len() {
            &[]
        } else {
            let end = usize::min(start + 8, chunk.len());
            &chunk[start..end]
        }
    }

    fn print_data_line(&self, writer: &mut dyn Write, chunk: &[u8], offset: u64) -> Result<()> {
        write!(writer, "{}", self.major_char())?;
        if self.config.use_color {
            write!(writer, "{}", self.config.palette.offset.prefix())?;
        }
        if self.config.show_position {
            write!(writer, "{offset:08x}")?;
            if self.config.use_color {
                write!(writer, "{RESET}")?;
            }
            write!(writer, "{}", self.major_char())?;
        }
        self.write_data_panels(writer, chunk, false)?;
        writeln!(writer)?;
        Ok(())
    }

    fn print_squeeze_line(&self, writer: &mut dyn Write) -> Result<()> {
        write!(writer, "{}", self.major_char())?;
        if self.config.show_position {
            if self.config.use_color {
                write!(writer, "{}", self.config.palette.offset.prefix())?;
            }
            write!(writer, "*")?;
            if self.config.use_color {
                write!(writer, "{RESET}")?;
            }
            write!(writer, "{}", " ".repeat(7))?;
            write!(writer, "{}", self.major_char())?;
            self.write_data_panels(writer, &[], false)?;
        } else {
            if self.config.use_color {
                write!(writer, "{}", self.config.palette.offset.prefix())?;
            }
            self.write_data_panels(writer, &[], true)?;
        }
        writeln!(writer)?;
        Ok(())
    }

    fn print_final_line(&self, writer: &mut dyn Write) -> Result<()> {
        if self.config.show_position {
            self.print_data_line(writer, &[], self.current_offset)
        } else {
            self.print_squeeze_line(writer)
        }
    }

    fn write_data_panels(
        &self,
        writer: &mut dyn Write,
        chunk: &[u8],
        squeeze_first_panel: bool,
    ) -> Result<()> {
        for panel in 0..self.config.panels {
            if panel > 0 {
                write!(writer, "{}", self.inner_char())?;
            }
            if squeeze_first_panel && panel == 0 {
                self.write_squeeze_hex_panel(writer)?;
            } else {
                self.write_hex_panel(writer, self.panel_slice(chunk, panel))?;
            }
        }
        if self.config.show_characters {
            write!(writer, "{}", self.major_char())?;
            for panel in 0..self.config.panels {
                if panel > 0 {
                    write!(writer, "{}", self.inner_char())?;
                }
                self.write_character_panel(writer, self.panel_slice(chunk, panel))?;
            }
        }
        write!(writer, "{}", self.major_char())?;
        Ok(())
    }

    fn write_squeeze_hex_panel(&self, writer: &mut dyn Write) -> Result<()> {
        if self.config.use_color {
            write!(
                writer,
                "{}*{RESET}",
                self.config.palette.offset.prefix()
            )?;
        } else {
            write!(writer, "*")?;
        }
        write!(writer, "{}", " ".repeat(self.hex_panel_width - 2))?;
        if self.config.use_color {
            write!(writer, "{RESET}")?;
        }
        write!(writer, " ")?;
        Ok(())
    }

    fn write_hex_panel(&self, writer: &mut dyn Write, panel_bytes: &[u8]) -> Result<()> {
        write!(writer, " ")?;
        let inner_width = self.hex_panel_width - 2;
        let mut written = 0_usize;
        let mut current_color: Option<Color> = None;
        let groups = 8 / self.config.group_size;

        for group in 0..groups {
            let start = group * self.config.group_size;
            if start >= panel_bytes.len() {
                break;
            }
            if group > 0 {
                write!(writer, " ")?;
                written += 1;
            }
            let end = usize::min(start + self.config.group_size, panel_bytes.len());
            let group_bytes = &panel_bytes[start..end];
            if self.config.little_endian {
                for byte in group_bytes.iter().rev() {
                    self.write_colored_byte_representation(
                        writer,
                        *byte,
                        &mut current_color,
                        &mut written,
                    )?;
                }
            } else {
                for byte in group_bytes {
                    self.write_colored_byte_representation(
                        writer,
                        *byte,
                        &mut current_color,
                        &mut written,
                    )?;
                }
            }
        }

        if written < inner_width {
            write!(writer, "{}", " ".repeat(inner_width - written))?;
        }
        if self.config.use_color {
            write!(writer, "{RESET}")?;
        }
        write!(writer, " ")?;
        Ok(())
    }

    fn write_colored_byte_representation(
        &self,
        writer: &mut dyn Write,
        byte: u8,
        current_color: &mut Option<Color>,
        written: &mut usize,
    ) -> Result<()> {
        if self.config.use_color {
            let color = self.byte_colors[byte as usize];
            if *current_color != Some(color) {
                write!(writer, "{}", color.prefix())?;
                *current_color = Some(color);
            }
        }
        let representation = &self.representations[byte as usize];
        write!(writer, "{representation}")?;
        *written += representation.len();
        Ok(())
    }

    fn write_character_panel(&self, writer: &mut dyn Write, panel_bytes: &[u8]) -> Result<()> {
        let mut current_color: Option<Color> = None;
        for byte in panel_bytes {
            if self.config.use_color {
                let color = self.byte_colors[*byte as usize];
                if current_color != Some(color) {
                    write!(writer, "{}", color.prefix())?;
                    current_color = Some(color);
                }
            }
            write!(writer, "{}", self.map_character(*byte))?;
        }
        if panel_bytes.len() < 8 {
            write!(writer, "{}", " ".repeat(8 - panel_bytes.len()))?;
        }
        if self.config.use_color {
            write!(writer, "{RESET}")?;
        }
        Ok(())
    }

    fn map_character(&self, byte: u8) -> char {
        match self.config.character_table {
            CharacterTable::Default => {
                if byte == 0 {
                    '⋄'
                } else if byte == b' ' {
                    ' '
                } else if byte.is_ascii_whitespace() {
                    '_'
                } else if (0x21..=0x7e).contains(&byte) {
                    byte as char
                } else if byte < 0x80 {
                    '•'
                } else {
                    '×'
                }
            }
            CharacterTable::Ascii => {
                if (0x20..=0x7e).contains(&byte) {
                    byte as char
                } else {
                    '.'
                }
            }
            CharacterTable::Codepage1047 => CP1047_TABLE[byte as usize],
            CharacterTable::Codepage437 => CP437_TABLE[byte as usize],
            CharacterTable::Braille => BRAILLE_TABLE[byte as usize],
        }
    }
}
