                ])
                .help("Whether to draw a border"),
        )
        .arg(
            Arg::new("plain")
                .short('p')
                .long("plain")
                .action(ArgAction::SetTrue)
                .help("Display output with --no-characters, --no-position, --border=none, and --color=never"),
        )
        .arg(
            Arg::new("no-characters")
                .long("no-characters")
